import React from 'react';

const events = [
  { month: 'MAY', day: '10' },
  { month: 'JULY', day: '10' },
  { month: 'MON', day: 'DD' },
];

export default function Events() {
  return (
      <section className="text-center px-[5vw] mb-20">
        <h2 className="text-xl sm:text-2xl md:text-3xl font-bold mb-6">Upcoming Events</h2>
        <div className="flex flex-col gap-6">
          {["MAY 10", "JULY 10", "MON DD"].map((date, idx) => (
            <div
              key={idx}
              className="flex flex-col sm:flex-row items-start sm:items-center bg-white p-6 rounded-2xl shadow-sm w-full"
            >
              <div className="bg-[#F48F0F] text-white text-center rounded-xl py-2 px-4 w-20">
                {date.split(" ")[0]}<br />{date.split(" ")[1]}
              </div>
              <div className="text-left mt-4 sm:mt-0 sm:ml-6">
                <strong className="text-base sm:text-lg md:text-xl">Event name goes here</strong>
                <p className="text-sm sm:text-base">
                  Event description or details would be displayed here (max 2 lines)
                </p>
              </div>
            </div>
          ))}
        </div>
        <button className="mt-6 bg-[#F48F0F] text-[#292929] py-2 px-6 rounded-full font-semibold text-sm sm:text-base">
          View All Events
        </button>
      </section>

  );
}
